<?php
require_once '../config/database.php'; require_once '../includes/auth.php'; require_role('student');$page_title='Моё расписание';
$q=$pdo->prepare('SELECT group_id FROM students WHERE user_id=?');$q->execute([$_SESSION['user']['id']]);$groupId=(int)$q->fetchColumn();
$from=$_GET['from']??date('Y-m-d',strtotime('-3 days'));$to=$_GET['to']??date('Y-m-d',strtotime('+14 days'));
$q=$pdo->prepare("SELECT l.*,s.name subject_name,CONCAT(t.surname,' ',t.name,' ',t.patronymic) teacher_name,g.name group_name FROM lessons l JOIN subjects s ON s.id=l.subject_id JOIN teachers t ON t.id=l.teacher_id JOIN groups g ON g.id=l.group_id WHERE l.group_id=? AND l.lesson_date BETWEEN ? AND ? ORDER BY l.lesson_date,l.start_time");$q->execute([$groupId,$from,$to]);$rows=$q->fetchAll();include '../includes/header.php';?>
<div class="panel"><form class="filters" method="get"><label>С <input type="date" name="from" value="<?=htmlspecialchars($from)?>"></label><label>По <input type="date" name="to" value="<?=htmlspecialchars($to)?>"></label><button class="btn">Показать</button></form></div>
<div class="panel" style="margin-top:20px"><h2>Занятия</h2><?php if($rows):?><div class="schedule-list"><?php foreach($rows as $r):$today=$r['lesson_date']===date('Y-m-d');?><div class="schedule-item <?=$today?'today-mark':''?>"><div><b><?=date('d.m',strtotime($r['lesson_date']))?></b><br><small><?=['Sun'=>'Вс','Mon'=>'Пн','Tue'=>'Вт','Wed'=>'Ср','Thu'=>'Чт','Fri'=>'Пт','Sat'=>'Сб'][date('D',strtotime($r['lesson_date']))]?></small></div><div><b><?=htmlspecialchars($r['subject_name'])?></b><br><small><?=htmlspecialchars($r['lesson_type'])?> · <?=htmlspecialchars(trim($r['teacher_name']))?></small></div><div class="schedule-time"><?=substr($r['start_time'],0,5)?>–<?=substr($r['end_time'],0,5)?><br><small>ауд. <?=htmlspecialchars($r['classroom'])?></small></div></div><?php endforeach;?></div><?php else:?><div class="empty-state"><div class="emoji">📅</div>На выбранный период занятий нет.</div><?php endif;?></div>
<?php include '../includes/footer.php';?>
